import { validateUiDocument, type UiDocument } from "@keating/learner-contracts";

export interface ExtractedUiDocuments {
  content: string;
  documents: UiDocument[];
  errors: string[];
}

const OPENING_FENCE = /^```(?:keating-ui|ui-document|openui-json|openui)(?:[ \t]+[^\n]*)?\n/gm;
const MAX_DOCUMENTS = 8;

/**
 * Compiles the JSON interchange form of Keating OpenUI into validated shared
 * documents. Browser OpenUI source is never evaluated on-device.
 */
export function extractUiDocuments(source: string): ExtractedUiDocuments {
  const documents: UiDocument[] = [];
  const errors: string[] = [];
  const text: string[] = [];
  let cursor = 0;
  OPENING_FENCE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = OPENING_FENCE.exec(source)) !== null) {
    const bodyStart = OPENING_FENCE.lastIndex;
    const closingMatch = /^```[ \t]*$/m.exec(source.slice(bodyStart));
    if (!closingMatch) break;
    const bodyEnd = bodyStart + closingMatch.index;
    const fenceEnd = bodyEnd + closingMatch[0].length;
    const body = source.slice(bodyStart, bodyEnd).trim();
    text.push(source.slice(cursor, match.index));
    if (documents.length >= MAX_DOCUMENTS) {
      errors.push("This response contains more interactive documents than mobile can safely render.");
    } else {
      try {
        const candidate = JSON.parse(body) as unknown;
        if (!validateUiDocument(candidate)) throw new Error("document schema is invalid");
        if (!candidate.supportedSurfaces.includes("mobile")) {
          errors.push(`Interactive document ${candidate.id} does not declare mobile support.`);
        } else {
          documents.push(candidate);
        }
      } catch (error) {
        errors.push(error instanceof Error
          ? `Interactive document could not be rendered: ${error.message}.`
          : "Interactive document could not be rendered.");
      }
    }
    cursor = fenceEnd;
    if (source[cursor] === "\n") cursor += 1;
    OPENING_FENCE.lastIndex = cursor;
  }
  text.push(source.slice(cursor));
  return { content: text.join("").trim(), documents, errors };
}

/** Prevent partially streamed JSON from flashing as a code block. */
export function hideUnclosedUiDocumentFence(source: string): string {
  OPENING_FENCE.lastIndex = 0;
  let match: RegExpExecArray | null;
  let lastUnclosed = -1;
  while ((match = OPENING_FENCE.exec(source)) !== null) {
    const closing = /^```[ \t]*$/m.exec(source.slice(OPENING_FENCE.lastIndex));
    if (!closing) {
      lastUnclosed = match.index;
      break;
    }
    OPENING_FENCE.lastIndex += closing.index + closing[0].length;
  }
  return lastUnclosed < 0 ? source : source.slice(0, lastUnclosed).trimEnd();
}

